ucs.falcon_logscale_query:
(#event_simpleName=ProcessRollup2)
| (ImageFileName=/\\wmic\.exe$/i AND regex("(?i)/node:", field=CommandLine))
  OR (ImageFileName=/\\procdump(64)?\.exe$/i AND CommandLine=/lsass/i)
  OR (regex("(?i)comsvcs\.dll", field=CommandLine) AND regex("(?i)minidump", field=CommandLine) AND regex("(?i)lsass", field=CommandLine))
  OR (ImageFileName=/\\ntdsutil\.exe$/i AND regex("(?i)(ifm|create\s+full|snapshot)", field=CommandLine))
| case {
    ImageFileName=/\\wmic\.exe$/i | activity := "wmic_node";
    ImageFileName=/\\ntdsutil\.exe$/i | activity := "ntds_dump";
    * | activity := "lsass_dump";
  }
| groupBy([aid, ComputerName, UserName], function=([count(field=activity, distinct=true, as=activity_kinds), collect([activity, ImageFileName, CommandLine]), min(@timestamp, as=firstSeen), max(@timestamp, as=lastSeen)]))
| activity_kinds >= 2
| sort(firstSeen, order=desc)
